INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('‘It’s not your dog’s fault, it’s yours’ – new awareness campaign launched', 'its-not-your-dogs-fault-its-yours-new-awareness-campaign-launched', '<p><span>The campaign, entitled ‘It’s not your dog’s fault, it’s yours’, is aimed at increasing awareness of the harm that out of control dogs can do to people and to livestock.</span></p>
<p><span>The goal is to change behaviour and to remind owners that they must always have their dog under control.</span></p>
<p><span>“Being a dog owner is a privilege, but it comes with a lot of responsibilities. We have seen far too many devastating attacks by dogs on people, especially young children, in recent times.</span></p>
<p><span>“I know the majority of dog owners are responsible and do the right thing. But we can all be guilty of thinking our dog wouldn’t hurt a fly,” said Minister Humphreys.</span></p>
<p><span>“No matter how harmless a dog might seem, they can be capable of causing a lot of damage. Ultimately, as the campaign says: it’s not your dog’s fault, it’s yours. Dog owners must make sure their dog is under control at all times, not running wild endangering people, livestock or other dogs,” she added.</span></p>
<figure aria-describedby="caption-attachment-254199"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/04/dogs-scaled.jpeg" alt="" width="1841" height="2560" srcset="https://changingireland.ie/wp-content/uploads/2024/04/dogs-scaled.jpeg 1841w, https://changingireland.ie/wp-content/uploads/2024/04/dogs-216x300.jpeg 216w, https://changingireland.ie/wp-content/uploads/2024/04/dogs-737x1024.jpeg 737w, https://changingireland.ie/wp-content/uploads/2024/04/dogs-768x1068.jpeg 768w, https://changingireland.ie/wp-content/uploads/2024/04/dogs-1105x1536.jpeg 1105w, https://changingireland.ie/wp-content/uploads/2024/04/dogs-1473x2048.jpeg 1473w, https://changingireland.ie/wp-content/uploads/2024/04/dogs-1080x1501.jpeg 1080w" sizes="(max-width: 1841px) 100vw, 1841px" /><figcaption><em>&#8211; Minister for Rural and Community Development, Heather Humphreys with retired Deputy Garda Commissioner John Twomey, chair of the Dog Control Stakeholder Group.</em></figcaption></figure>
<p><span>This campaign follows closely from a series of related initiatives:</span></p>
<ul>
<li aria-level="1"><span>Increases in on-the-spot fines up to €300</span></li>
<li aria-level="1"><span>An additional €2 million to support dog pounds</span></li>
<li aria-level="1"><span>The establishment of the Dog Control Stakeholder Group.</span></li>
</ul>
<p><span>Minister for Agriculture, Food and the Marine Charlie McConalogue also welcomed the campaign, sharing his hope that it will encourage wider conversations on dog owner responsibilities.</span></p>
<p><span>He commented: “I know how traumatic dog attacks can be to people, especially children. I am also acutely aware of the devastation done to livestock by marauding dogs, causing terrible suffering to the animals and both emotional and financial distress to farming families.</span></p>
<p><span>“I believe it is essential we have conversations about responsible dog ownership and illustrating the dangers of marauding dogs, protecting people and animals from dog attacks.”</span></p>
<p><span>Visit </span><a href="https://gov.ie/dogs"><span>gov.ie/dogs</span></a><span> to find out more.</span></p>', 'Minister for Rural and Community Development, Heather Humphreys has launched a major national awareness campaign to remind dog owners of their responsibilities.', 'https://changingireland.ie/wp-content/uploads/2024/04/Screenshot_20240422_160925_X.jpg', '', '[{"slug":"planning-governance","title":"Planning & Governance"}]', '[{"slug":"animal-welfare","title":"animal welfare"},{"slug":"department-of-agriculture-food-and-the-marine","title":"Department of Agriculture Food and the Marine"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"dog-control","title":"Dog control"},{"slug":"dog-control-stakeholder-group","title":"Dog Control Stakeholder Group"},{"slug":"dog-owners","title":"dog owners"},{"slug":"farming","title":"farming"},{"slug":"livestock","title":"livestock"},{"slug":"minister-charlie-mcconalogue","title":"Minister Charlie McConalogue"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"}]', '', 254197, 1, '2024-04-23T10:01:00Z', '2024-04-23T10:39:35Z', '2024-04-23T10:01:00Z')
