INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€30 million funding provided for 12 new community centres', 'e30-million-funding-provided-for-12-new-community-centres', '<p><span>An investment of more than €30 million to provide 12 new community centres across Ireland was announced this week. </span></p>
<p><span>It is the first time in the history of the State that a dedicated fund has been set up to deliver new-build community centres in rural Ireland.</span></p>
<p><span>Minister for Rural and Community Development, Heather Humphreys made the announcement while visiting Newcastle in Galway, which is to receive over €4.3 million to build a brand new community centre.</span></p>
<p><span>The successful community centre projects will receive capital grants of between €1 million and €6 million to build multi-functional centres in areas that currently lack community facilities. </span></p>
<p><span>The Community Centres Investment Fund was launched in March 2023 to provide investment for new and ambitious community projects in towns and villages nationwide.    </span></p>
<p><span>After providing funding of €45.8m to over 860 projects for refurbishments, Minister Humphreys said she decided to put a renewed focus on supporting communities that have no community centre at all. </span></p>
<p><span> The 12 projects to receive funding are:</span></p>
<ul>
<li><span>       Aras Lae, Maigh Cuilinn, Co Galway &#8211; €6,000,000</span></li>
<li><span>       Tullow Road Community Hub, Carlow Town &#8211; €4,135,178.</span></li>
<li><span>       Newcastle Community Centre, Galway City &#8211; €4,343,255.</span></li>
<li><span>       Rylane Community Centre, Co Cork &#8211; €1,595,574</span></li>
<li><span>       Ballina Scouting Den and Community Centre, Co Mayo &#8211; €1,152,193</span></li>
<li><span>       Kilcloon Community Centre, Co Meath: &#8211; €1,915,000</span></li>
<li><span>       Rockcorry Community Centre, Co Monaghan: &#8211; €2,667,785</span></li>
<li><span>       Moneygall Community Centre, Co Offaly &#8211; €1,407,660</span></li>
<li><span>       Ballymote Community Centre, Co Sligo &#8211; €2,650,991</span></li>
<li><span>       Kilglass Community Centre, Co Sligo &#8211; €1,163,710</span></li>
<li><span>       Ballymitty Community Development, Co Wexford &#8211; €1,398,035</span></li>
<li><span>       Riverchapel Community Centre, Co Wexford &#8211; €1,797,919</span></li>
</ul>
<p><span>Minister Humphreys said the investment would be “transformational for our rural towns and villages”.</span></p>
<p><span>&#8220;Our community centres bring people of all ages together, whether it be for sporting, educational or social occasions. </span><span>They are vital for engaging with those who may find themselves marginalised and they give everyone in the community a great sense of belonging.”</span></p>
<p><span>She continued: &#8220;They build, stronger, more vibrant communities – places that for so many people act as a home from home. You could say that the community centre is the cornerstone of community life in many towns, villages and cities around the country.”</span></p>
<p><span>The projects are all on brown or green field sites and have all the necessary planning and consents secured so they are already at an advanced stage and ready to commence following a tender process. </span></p>
<p><span>The fund targets areas without an appropriate facility to meet their community&#8217;s needs.  The centres range in size from single storey to two-storey buildings and will be located in rural and urban settings across nine counties.</span></p>', '12 projects in areas that currently lack a community centre will receive between €1 million and €6 million to build brand new facilities.', 'https://changingireland.ie/wp-content/uploads/2024/04/newcastle3.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"carlow","title":"Carlow"},{"slug":"community","title":"Community"},{"slug":"community-centres","title":"Community centres"},{"slug":"community-centres-investment-fund","title":"Community Centres Investment Fund"},{"slug":"community-development","title":"community development"},{"slug":"cork","title":"Cork"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"funding","title":"funding"},{"slug":"galway","title":"Galway"},{"slug":"government-funding","title":"government funding"},{"slug":"mayo","title":"Mayo"},{"slug":"meath","title":"Meath"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"monaghan","title":"Monaghan"},{"slug":"offaly","title":"Offaly"},{"slug":"rural-development","title":"rural development"},{"slug":"sligo","title":"Sligo"},{"slug":"wexford","title":"Wexford"}]', '', 254176, 1, '2024-04-22T09:32:42Z', '2024-04-22T09:32:42Z', '2024-04-22T09:32:42Z')
