INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€400,000 funding to upgrade 43 walking trails', 'e400000-funding-to-upgrade-43-walking-trails', '<p><span>The investment is designed to open up our countryside to visitors and make Ireland a world class destination for adventure tourism. </span></p>
<p><span> </span><span>The funding will improve trail surfaces, drainage, waymarking and signage, enhancing these trails and the surrounding countryside.</span></p>
<p><span> </span><span>It will also provide seating, picnic and recreation areas, and reroute some trails which will enhance the experience of those using them. These projects are being delivered in partnership with landowners, Local Development Companies, Community Trail Management Organisations and other stakeholders.</span></p>
<p><span>Under the Walks Scheme, funding is provided to farmers and other landholders to maintain the trails that cross their land.</span></p>
<p><span> </span><span>The successful projects to receive a funding allocation include:</span><span> </span></p>
<ul>
<li aria-level="1"><span>Hymany Way, Forum Connemara: Resurface trail and install drainage &#8211; €10,000</span></li>
<li aria-level="1"><span>Dingle Way, North East West Kerry Development: Path upgrade, installation of new trail head map board in Tralee and installation of a self-closing pedestrian gate. &#8211; €10,000</span></li>
<li aria-level="1"><span>Leitrim Way, Leitrim Development Company: Resurface trail, drainage and installation of a bog bridge, 2 picnic benches and a stile. &#8211; €10,000</span></li>
<li aria-level="1"><span>Multeen Way, South Tipperary Development Company Ltd: Resurface trail and install drainage &#8211; €10,000</span></li>
<li aria-level="1"><span>Western Way, South West Mayo Development Company: Replacement of damaged wooden bridge with galvanised version &#8211; €10,000</span></li>
<li aria-level="1"><span>Wicklow Way, County Wicklow Partnership: Resurface trail and install reverse grade waterbars to assist drainage &#8211; €10,000</span></li>
<li aria-level="1"><span>Sheep&#8217;s Head Way, West Cork Development Partnership:  Upgrade of signage on trail and improving trail at Gortnakilla &amp; Funeral Path &#8211; €10,000</span></li>
</ul>
<figure aria-describedby="caption-attachment-254171"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/04/IMG_3857-scaled.jpg" alt="" width="2560" height="1707" srcset="https://changingireland.ie/wp-content/uploads/2024/04/IMG_3857-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2024/04/IMG_3857-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2024/04/IMG_3857-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2024/04/IMG_3857-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2024/04/IMG_3857-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2024/04/IMG_3857-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2024/04/IMG_3857-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption><em>&#8211; Pictured with Minister Humphreys at Bóthar Na Naomh Walking Trail in Cloone, Co Leitrim are local walkers Lily Mitchell (left) and Collette Charles (right).</em></figcaption></figure>
<p><span>Minister for Rural and Community Development, Heather Humphreys said: &#8220;There is no better way of seeing our beautiful countryside than to use the many trails and walkways that are dotted around the country.</span></p>
<p><span> </span><span>&#8220;These trails, many of which were created by volunteers and community groups, need to be cherished and maintained, so they can continue to be enjoyed by all.</span></p>
<p><span> </span><span>&#8220;These projects will also see investment into the local economy as they are carried out by small contractors using materials from local suppliers.</span></p>
<p><span>&#8220;The collaboration between community groups and local development companies behind the upgrade and enhancement of these trails is wonderful to see and I commend everyone for their great work.”</span></p>', 'A funding boost of €408,000 will be provided to resurface, re-route and improve 43 rural outdoor trails across 14 counties under the Government’s Walks Scheme.', 'https://changingireland.ie/wp-content/uploads/2024/04/IMG_20211230_163737_618-e1713183496694.jpg', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"community-trail-management-organisations","title":"community trail management organisations"},{"slug":"cork","title":"Cork"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"funding","title":"funding"},{"slug":"galway","title":"Galway"},{"slug":"hiking","title":"hiking"},{"slug":"kerry","title":"Kerry"},{"slug":"laois","title":"Laois"},{"slug":"leitrim","title":"Leitrim"},{"slug":"local-development-companies","title":"local development companies"},{"slug":"mayo","title":"Mayo"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"tipperary","title":"Tipperary"},{"slug":"walking-trails","title":"walking trails"},{"slug":"walks-scheme-development-fund","title":"Walks Scheme Development Fund"},{"slug":"wicklow","title":"Wicklow"}]', '', 254169, 1, '2024-04-15T12:27:11Z', '2024-04-15T12:27:11Z', '2024-04-15T12:27:11Z')
