INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Islanders astounded as first child born on Árainn Mhór since 1970s', 'islanders-astounded-as-first-child-born-on-arainn-mhor-since-1970s', '<p>“Our baby is called Marvin. If it was a girl we were going to call him Maire,” said Alexander.</p>
<p>“Everyone asked did we go by helicopter or by boat (as expectant mothers normally do). “I said, ‘Neither’. They said ‘How then?’ and I told them. I was sleeping and Slava gave birth to the baby in the next room. I was asleep with two of our children and I woke up to the sound of crying, so I looked at the children in the bed and neither was crying. It was then my sleepy brain told me that our baby was born.”</p>
<p>Marvin is the first baby born on Árainn Mhór since the 1970s.</p>
<p>“For the baby it’s very good here, quiet and peaceful,” said Alexander. “When he was a newborn we used to walk to a beach with him while he was sleeping, enjoying the quiet. We used to live in a city and it was so loud, there were so many people. It’s a huge contrast to be here. It’s perfect for the children.</p>
<p>“I used to work as a graphic designer and we had an e-commerce store,&#8221; he said.</p>
<p>Could he find work here?</p>
<p>&#8220;Right now I am too busy home-parenting. I do some part-time jobs for my Ukrainian friends (abroad), but we don’t have many friends here yet so it’s hard to find a babysitter,” he said.</p>
<p>When his family first came to Ireland, they were allocated accommodation in a village in Co. Sligo. Then they were brought to Árainn Mhór and Alex says there is no comparison: &#8220;I think Arranmore’s community is just perfect.&#8221;</p>
<p>He pointed, for example, to the Active Arranmore activities on the island for all ages: “I met Alex (another Alex, also Ukrainian) through the chess tournament. Then our sons met.&#8221;</p>
<p><strong>For more on Arranmore&#8217;s Ukrainian community, read <a href="https://changingireland.ie/vlad-oleg-julia-…e-on-arainn-mhor/">here</a> about how some of the island&#8217;s new residents are adapting to the change from city life.</strong></p>
<blockquote><p><a href="https://changingireland.ie/empowering-communities-funding-led-to-best-project-in-20-years-arranmore/">Island&#8217;s brilliant example of how community workers change lives</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Island’s brilliant example of how community workers change lives” — Changing Ireland" src="https://changingireland.ie/empowering-communities-funding-led-to-best-project-in-20-years-arranmore/embed/#?secret=M5juoPQZrI#?secret=39pRbvHRhc" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<p>&nbsp;</p>', 'In a recent visit to Árainn Mhór, Allen Meagher was hoping to meet one particular Ukrainian family. The whole family could not make it, but Alexander, proud father of five children, told the story that astounded locals.', 'https://changingireland.ie/wp-content/uploads/2024/03/IMG_5882-scaled.jpg', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[{"slug":"changingdonegal","title":"#ChangingDonegal"},{"slug":"arainn-mhor","title":"Árainn Mhór"},{"slug":"arranmore","title":"Arranmore"},{"slug":"community-development","title":"community development"},{"slug":"donegal","title":"Donegal"},{"slug":"refugees","title":"refugees"},{"slug":"rural-development","title":"rural development"},{"slug":"ukraine","title":"Ukraine"},{"slug":"ukrainian-refugees","title":"Ukrainian refugees"}]', '', 253860, 1, '2024-04-12T11:07:21Z', '2024-04-16T10:36:16Z', '2024-04-12T11:07:21Z')
