INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Tidy Towns groups seeking more young volunteers for 2024', 'tidy-towns-groups-seeking-more-young-volunteers-for-2024', '<p><span>At the recent launch of the competition, Minister for Rural and Community Development, Heather Humphreys urged people to get involved in their local Tidy Towns group, especially young people.</span></p>
<p><span> Taking</span><span> place annually since 1958, the competition, administered by the Department of Rural and Community Development and sponsored by SuperValu, has grown into a national sustainability movement.</span></p>
<p><span> </span><span>&#8220;Tidy Towns is all about people, places and possibilities. Everywhere is unique and the competition provides a platform to share what is best about communities across Ireland.</span></p>
<p><span>“Being part of your local Tidy Towns group is a great way to transform your town into a vibrant, inclusive and sustainable place for everyone,” said Minister Humphreys.</span></p>
<p><span>Also speaking at the launch was Ian Allen, managing director of SuperValu. He said: &#8220;SuperValu Tidy Towns has become an integral part of community life in towns and villages across Ireland. It is a powerful, uniting force, which shows what can be achieved when communities work together towards the common goal of improving their local areas to make them better, more sustainable places to live, work and play.</span></p>
<p><span>&#8220;I have been particularly delighted to witness in recent years how the initiative has evolved to increase its focus on sustainable climate action and biodiversity projects mobilising thousands of people to make a positive and lasting impact in their communities. I am also deeply heartened by the mix of young and experienced volunteers ensuring that SuperValu Tidy Towns goes from strength to strength and continues to innovate each year.&#8221;</span></p>
<p><span>The competition features a number of Special Awards, such as the All Ireland Pollinator Plan Award, the Young Persons in Tidy Towns Award, the Heritage Award and the Leave No Trace Award among others.</span></p>
<p><span>Following on from last year&#8217;s inaugural Town Centre First Award, the category is continuing this year as an official Supervalu Tidy Towns Special Award, to recognise exemplary efforts made by towns in driving forward town centre revitalisation in line with Town Centre First policy.</span></p>
<p><span>The closing date for receipt of entries for this year&#8217;s competition is Wednesday, May 8. Entry will only be accepted by email to tidytowns@drcd.gov.ie. Entry forms for the SuperValu Tidy Towns competition are available at </span><a href="http://www.tidytowns.ie/"><span>www.tidytowns.ie</span></a><span> and will be emailed to all registered groups.</span></p>
<p><span>Full details of the competition are available on </span><a href="http://www.tidytowns.ie/"><span>www.tidytowns.ie</span></a><span> or </span><a href="http://www.supervalu.ie/"><span>www.supervalu.ie</span></a></p>', 'Entries are now open for the 2024 SuperValu Tidy Towns competition, marking the 66th consecutive year of the event. Last year, 880 entries were received, with more than 30,000 volunteers working across 1,000 active Tidy Towns groups in towns and villages nationwide.', 'https://changingireland.ie/wp-content/uploads/2024/04/tidy-towns.jpg', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"climate-action","title":"climate action"},{"slug":"community","title":"Community"},{"slug":"community-development","title":"community development"},{"slug":"competition","title":"competition"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"leave-no-trace","title":"Leave No Trace"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"pollinator","title":"pollinator"},{"slug":"rural-development","title":"rural development"},{"slug":"supervalu","title":"SuperValu"},{"slug":"supervalu-tidy-towns-competition","title":"SuperValu Tidy Towns Competition"},{"slug":"tidy-towns","title":"Tidy Towns"},{"slug":"town-centre-first","title":"Town Centre First"},{"slug":"volunteers","title":"volunteers"}]', '', 254120, 1, '2024-04-02T15:16:18Z', '2024-04-02T15:18:17Z', '2024-04-02T15:16:18Z')
