INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('“It’s crazy burning buildings – we’d take another 100 or more people” – John McCafferty', 'its-crazy-burning-buildings-wed-take-another-100-or-more-people-john-mccafferty', '<p>&#8220;Burning down places that might be used. I don’t understand that. It’s crazy stuff. You don’t know where we come from. I just don’t get it,&#8221; he remarked. &#8220;My mum and dad worked away. It was an Irish thing back then – when we didn’t have work, when you couldn’t go fishing anymore.&#8221;</p>
<p>He suggests people thinking of arson &#8220;should be using their time to add to their community, trying to improve things, and if there’s an issue there, sit down and sort it out. Don’t be burning buildings, throwing stones, burning buses. It’s getting like famine time evictions,&#8221; said John.</p>
<p>&#8220;Who knows, in ten or twenty years down the road, we may be in that same boat. We may have to go somewhere. My kids might have to go somewhere.</p>
<p>&#8220;At the moment West Donegal is cleared out with kids who have gone for a while. My two nephews are in Australia. I’d love my two kids to stay local, but they might go. If I thought Australians were going to burn accommodation for them…&#8221;</p>
<p>His island has welcomed dozens of refugees.</p>
<figure aria-describedby="caption-attachment-253931"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/03/Arranmores-community-centre-on-St-Patricks-Day-photo-courtesy-CFFAM.jpg" alt="" width="2048" height="1536" srcset="https://changingireland.ie/wp-content/uploads/2024/03/Arranmores-community-centre-on-St-Patricks-Day-photo-courtesy-CFFAM.jpg 2048w, https://changingireland.ie/wp-content/uploads/2024/03/Arranmores-community-centre-on-St-Patricks-Day-photo-courtesy-CFFAM-300x225.jpg 300w, https://changingireland.ie/wp-content/uploads/2024/03/Arranmores-community-centre-on-St-Patricks-Day-photo-courtesy-CFFAM-1024x768.jpg 1024w, https://changingireland.ie/wp-content/uploads/2024/03/Arranmores-community-centre-on-St-Patricks-Day-photo-courtesy-CFFAM-768x576.jpg 768w, https://changingireland.ie/wp-content/uploads/2024/03/Arranmores-community-centre-on-St-Patricks-Day-photo-courtesy-CFFAM-1536x1152.jpg 1536w, https://changingireland.ie/wp-content/uploads/2024/03/Arranmores-community-centre-on-St-Patricks-Day-photo-courtesy-CFFAM-1080x810.jpg 1080w" sizes="(max-width: 2048px) 100vw, 2048px" /><figcaption><em>• Arranmore&#8217;s community centre on St Patrick&#8217;s Day-photo courtesy CFFAM.</em></figcaption></figure>
<p>&#8220;Those people who have come here and are actively taking part are adding to communities,&#8221; he revealed.</p>
<p>John was dismayed at the way Irish identity may be changing.</p>
<p>&#8220;The Irish have always been known for being welcoming and open and willing to help people. I’d hate to see Ireland change so much that we lose that. That’s our identity.</p>
<p>&#8220;People from Ireland have gone to far-flung places trying to help others. I would hate Ireland to lose that identity,&#8221; he added.<br />
Árainn Mhór has a permanent population of just under 500 people, including 30 or so Ukrainians. The summertime population rises to between 1,500 and 2,000 people.</p>
<p>&#8220;If we had the housing and the infrastructure here, I’d happily welcome another 100 or more Ukrainians, Syrians or whatever. They’re in desperate need. They’re not leaving their country for a jolly, they need help. The people already here are actively involved in the community, they’re trusted.</p>
<p>&#8220;I’d love to think that if the shoe was on the other foot the option to leave was available to me and my family,&#8221; said John.</p>
<p>Driving two of us around the island, we passed a 16-bed hotel the government could consider purchasing which has been up for sale for the past four years.</p>
<blockquote><p><a href="https://changingireland.ie/empowering-communities-funding-led-to-best-project-in-20-years-arranmore/">Island&#8217;s brilliant example of how community workers change lives</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Island’s brilliant example of how community workers change lives” — Changing Ireland" src="https://changingireland.ie/empowering-communities-funding-led-to-best-project-in-20-years-arranmore/embed/#?secret=3NFQkEgJOI#?secret=aCpT01vgd2" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'John McCafferty says that Árainn Mhór island in Co. Donegal would welcome another 100 or more people fleeing war and strife. He objects as an Irish person, proud of our history, to arson as a form of protest and does not understand why anyone would engage in such acts.', 'https://changingireland.ie/wp-content/uploads/2024/03/There-are-two-ferries-the-red-ferry-and-the-green-ferry.png', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[{"slug":"changingdonegal","title":"#ChangingDonegal"},{"slug":"anti-racism","title":"anti-racism"},{"slug":"arranmore","title":"Arranmore"},{"slug":"community","title":"Community"},{"slug":"community-development","title":"community development"},{"slug":"donegal","title":"Donegal"},{"slug":"gaeltacht","title":"Gaeltacht"},{"slug":"human-rights","title":"human rights"},{"slug":"integration","title":"integration"},{"slug":"islands","title":"Islands"},{"slug":"refugees","title":"refugees"},{"slug":"rural-development","title":"rural development"},{"slug":"sanctuary","title":"sanctuary"},{"slug":"ukraine","title":"Ukraine"},{"slug":"ukrainians-in-ireland","title":"Ukrainians in Ireland"}]', '', 253859, 1, '2024-03-21T09:54:46Z', '2024-05-16T11:03:51Z', '2024-03-21T09:54:46Z')
