INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('From a Ukrainian city to “a rock” in Donegal', 'vlad-oleg-julia-and-alex-describe-life-on-arainn-mhor', '<p>Árainn Mhór&#8217;s population is concentrated on the sheltered eastern side of the island and is not as exposed or as isolated from the mainland as some of Ireland&#8217;s other offshore islands. Teenagers from the mainland even take the ferry to Árainn Mhór to attend secondary school.</p>
<p>For Ukrainians, they do not mind the weather so much. Vlad (who now runs Zumba classes on the island) arrived in a t-shirt during an August heatwave and was relieved when he found the winter not as cold as back home.</p>
<p>The only downside is the hour-long walk often in the dark from his house to the community centre. In fact, the Ukrainians are spread out in different houses on the island and have taken time to get to know each other.</p>
<p>The biggest change for Vlad was moving from a city to a rural part of Ireland. Oleg said: &#8220;It&#8217;s so safe and calm here. The people are good.&#8221;</p>
<p>Alex recalled: &#8220;When we first looked at the map of Ireland and found Arranmore, it was a rock. That was a shock.&#8221; He deeply appreciates the quality of education available on the island for his children aged 16 and four.</p>
<p>As an engineer, he has many ideas for community development &#8211; &#8220;every day&#8221; says his wife Yulia, who lost her job as a civil servant when her city was invaded. She likes the wild weather here, enjoys walking and she is now employed in the Day Care Centre on Árainn Mhór. Alex wants to join the RNLI as a volunteer.</p>
<p>&#8220;It is a very, very friendly and welcoming community. They stop us and have chats,&#8221; said Yulia.</p>
<p>&#8220;100%,&#8221; agreed Alex.</p>
<p><strong>For more on Arranmore&#8217;s new Ukrainian community, read our story <a href="https://changingireland.ie/islanders-astoun…mhor-since-1970s/">here</a> about the first baby born on the island since the 1970s.</strong></p>
<p><em>Since our meeting, Yulia&#8217;s mum Natalia had a mishap. The Arranmore community, having warmly welcomed the family, launched a fundraising campaign and asked Changing Ireland to share the link. It is a testament to the bonds formed between islanders and newcomers that they have raised over €4,500 in a short space of time. </em></p>
<p><em>More info:</em> <a href="https://www.idonate.ie/crowdfunder/nataliasupport"><em>https://www.idonate.ie/crowdfunder/nataliasupport</em></a></p>
<p><a href="https://www.idonate.ie/crowdfunder/nataliasupport"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/03/Natalias-crowdfunding-page.png" alt="" width="1031" height="716" srcset="https://changingireland.ie/wp-content/uploads/2024/03/Natalias-crowdfunding-page.png 1031w, https://changingireland.ie/wp-content/uploads/2024/03/Natalias-crowdfunding-page-300x208.png 300w, https://changingireland.ie/wp-content/uploads/2024/03/Natalias-crowdfunding-page-1024x711.png 1024w, https://changingireland.ie/wp-content/uploads/2024/03/Natalias-crowdfunding-page-768x533.png 768w" sizes="(max-width: 1031px) 100vw, 1031px" /></a></p>', 'From city life in Ukraine to “a rock” off the coast of Donegal – Árainn Mhór’s Ukrainian population have settled well into island life and their new community', 'https://changingireland.ie/wp-content/uploads/2024/03/IMG_5874-scaled.jpg', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[{"slug":"changingdonegal","title":"#ChangingDonegal"},{"slug":"arainn-mhor","title":"Árainn Mhór"},{"slug":"arranmore","title":"Arranmore"},{"slug":"arranmore-island","title":"Arranmore Island"},{"slug":"community","title":"Community"},{"slug":"community-development","title":"community development"},{"slug":"donegal","title":"Donegal"},{"slug":"ireland","title":"Ireland"},{"slug":"irelands-islands","title":"Ireland''s islands"},{"slug":"islands","title":"Islands"},{"slug":"refugees","title":"refugees"},{"slug":"ukraine","title":"Ukraine"},{"slug":"ukrainian-refugees","title":"Ukrainian refugees"},{"slug":"ukrainians-in-ireland","title":"Ukrainians in Ireland"},{"slug":"war-in-ukraine","title":"war in Ukraine"}]', '', 253861, 1, '2024-03-21T09:48:35Z', '2024-04-12T11:09:52Z', '2024-03-21T09:48:35Z')
