INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('The Football Co-op gives a €17.60 social return on every €1 invested', 'the-football-co-op-gives-a-e17-60-social-return-on-every-e1-invested', '<p>The Football Cooperative was one of the top Social Enterprise IMPACT Award winners this year (see more<span> <a href="https://changingireland.ie/trustworthy-social-enterprises-essential-to-combat-greenwashing-and-pinkwashing/">here),</a></span> and it unveiled research undertaken with academic partners that showed their social enterprise represented incredible value for money.</p>
<p>After 18 months research as part of a PhD, Waterford-based Dr Steve Daly from the South East Technological University (SETU) concluded that the Football Cooperative generated a Social Return on Investment (SROI) of €17.60 for each euro invested. He said this is about double what most social interventions are valued at.</p>
<p>He was assisted in his research by colleagues Dr. Paula Carroll, Dr, Tom Egan, Prof. Michael Harrison and Dr. Noel Richardson from SETU&#8217;s Department of Health Sciences. All stakeholder groups reported benefits and the research showed that the Football Co-operative was suitable for scale-up.</p>
<p>&#8220;We conducted environmental and situational analysis at prospective sites for replication,&#8221; said Steve.<img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operative-used-a-Social-Return-on-Investment-SROI-approach-to-calculate-social-value.png" alt="" width="1557" height="873" srcset="https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operative-used-a-Social-Return-on-Investment-SROI-approach-to-calculate-social-value.png 1557w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operative-used-a-Social-Return-on-Investment-SROI-approach-to-calculate-social-value-300x168.png 300w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operative-used-a-Social-Return-on-Investment-SROI-approach-to-calculate-social-value-1024x574.png 1024w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operative-used-a-Social-Return-on-Investment-SROI-approach-to-calculate-social-value-768x431.png 768w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operative-used-a-Social-Return-on-Investment-SROI-approach-to-calculate-social-value-1536x861.png 1536w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operative-used-a-Social-Return-on-Investment-SROI-approach-to-calculate-social-value-1080x606.png 1080w" sizes="(max-width: 1557px) 100vw, 1557px" /></p>
<p><em>• The Football Co-operative used a Social Return on Investment (SROI) approach to calculate social value.</em></p>
<p>The expansion plan is ambitious. <span>The project currently operates from just two sites, but hopes in the future to reach multiple communities not just in Ireland but internationally. It also wants to expand beyond holding cooperative football just one evening a week, and to scale outwards to get more hard-to-reach men to tog out for games.</span></p>
<figure aria-describedby="caption-attachment-254039"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/03/Stats-from-the-Football-Co-operative-on-participation-and-impact.png" alt="" width="1559" height="874" srcset="https://changingireland.ie/wp-content/uploads/2024/03/Stats-from-the-Football-Co-operative-on-participation-and-impact.png 1559w, https://changingireland.ie/wp-content/uploads/2024/03/Stats-from-the-Football-Co-operative-on-participation-and-impact-300x168.png 300w, https://changingireland.ie/wp-content/uploads/2024/03/Stats-from-the-Football-Co-operative-on-participation-and-impact-1024x574.png 1024w, https://changingireland.ie/wp-content/uploads/2024/03/Stats-from-the-Football-Co-operative-on-participation-and-impact-768x431.png 768w, https://changingireland.ie/wp-content/uploads/2024/03/Stats-from-the-Football-Co-operative-on-participation-and-impact-1536x861.png 1536w, https://changingireland.ie/wp-content/uploads/2024/03/Stats-from-the-Football-Co-operative-on-participation-and-impact-1080x605.png 1080w" sizes="(max-width: 1559px) 100vw, 1559px" /><figcaption><em>• Stats from the Football Co-operative on participation and impact.</em></figcaption></figure>
<p>Steven O&#8217;Connell, founder of the Football Cooperative, said, “We can help people feel part of a place. Last year, we had 608 participants and now we can prove that this model works. Our early intervention and health promotion programme takes a gendered approach, targeting men, and has a co-operative ethos. Volunteer co-ordinators arrange pitches, bibs, times and so on. Ultimately there is no substitute for exercise,” he said.</p>
<figure aria-describedby="caption-attachment-254043"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/03/Steve-Daly-PhD-researcher-and-Steven-OConnell-founder-of-the-Football-Coop-scaled.jpeg" alt="" width="2560" height="1883" srcset="https://changingireland.ie/wp-content/uploads/2024/03/Steve-Daly-PhD-researcher-and-Steven-OConnell-founder-of-the-Football-Coop-scaled.jpeg 2560w, https://changingireland.ie/wp-content/uploads/2024/03/Steve-Daly-PhD-researcher-and-Steven-OConnell-founder-of-the-Football-Coop-300x221.jpeg 300w, https://changingireland.ie/wp-content/uploads/2024/03/Steve-Daly-PhD-researcher-and-Steven-OConnell-founder-of-the-Football-Coop-1024x753.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2024/03/Steve-Daly-PhD-researcher-and-Steven-OConnell-founder-of-the-Football-Coop-768x565.jpeg 768w, https://changingireland.ie/wp-content/uploads/2024/03/Steve-Daly-PhD-researcher-and-Steven-OConnell-founder-of-the-Football-Coop-1536x1130.jpeg 1536w, https://changingireland.ie/wp-content/uploads/2024/03/Steve-Daly-PhD-researcher-and-Steven-OConnell-founder-of-the-Football-Coop-2048x1506.jpeg 2048w, https://changingireland.ie/wp-content/uploads/2024/03/Steve-Daly-PhD-researcher-and-Steven-OConnell-founder-of-the-Football-Coop-1080x794.jpeg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption><em>• Steve Daly, PhD researcher and Steven O&#8217;Connell, founder of the Football Coop with their award. They also received a share of €45,000 awarded to six overall winners &#8211;<a href="https://changingireland.ie/trustworthy-social-enterprises-essential-to-combat-greenwashing-and-pinkwashing/"><strong> full story here.</strong></a></em></figcaption></figure>
<p>Below is the slideshow &#8211; <strong>click the image</strong> &#8211; as presented in Tullamore when the Football Co-operative won an award for measuring its social impact. The outcomes are all backed up by rigorous research. For anyone considering measuring impact, we highly recommend this as an example of best practice. It&#8217;s also jaw-dropping what the Football Co-operative was able to demonstrate in terms of outcomes and value for money.</p>
<figure aria-describedby="caption-attachment-254040"><a href="https://changingireland.ie/wp-content/uploads/2024/03/NB-Football-Cooperative-ILDN-Impact-Awards-FINAL.pdf" target="_blank" rel="noopener"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operatives-20-slide-presentation.png" alt="" width="1546" height="872" srcset="https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operatives-20-slide-presentation.png 1546w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operatives-20-slide-presentation-300x169.png 300w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operatives-20-slide-presentation-1024x578.png 1024w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operatives-20-slide-presentation-768x433.png 768w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operatives-20-slide-presentation-1536x866.png 1536w, https://changingireland.ie/wp-content/uploads/2024/03/The-Football-Co-operatives-20-slide-presentation-1080x609.png 1080w" sizes="(max-width: 1546px) 100vw, 1546px" /></a><figcaption><em>• Above &#8211; <a href="https://changingireland.ie/wp-content/uploads/2024/03/NB-Football-Cooperative-ILDN-Impact-Awards-FINAL.pdf">click</a> to view or download the Football Co-operative&#8217;s 20-slide presentation.</em></figcaption></figure>
<p>If you wish to see men in your community become more active, healthier and connected, email Steven O&#8217;Connell at: <a href="mailto:footballcooperativeireland@gmail.com">footballcooperativeireland@gmail.com</a></p>
<p>You can connect with the Football Co-operative via Facebook: <a href="https://www.facebook.com/footballcooperative/" target="_blank" rel="noopener">https://www.facebook.com/footballcooperative/</a></p>
<blockquote><p><a href="https://changingireland.ie/measuring-social-impact-learn-from-those-who-won-e45k/">Measuring social impact: Learn from those who won €45k</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Measuring social impact: Learn from those who won €45k” — Changing Ireland" src="https://changingireland.ie/measuring-social-impact-learn-from-those-who-won-e45k/embed/#?secret=36tNRoukIr#?secret=yMyIPPOKBc" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/trustworthy-social-enterprises-essential-to-combat-greenwashing-and-pinkwashing/">Trustworthy social enterprises essential to combat greenwashing and pinkwashing</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Trustworthy social enterprises essential to combat greenwashing and pinkwashing” — Changing Ireland" src="https://changingireland.ie/trustworthy-social-enterprises-essential-to-combat-greenwashing-and-pinkwashing/embed/#?secret=gDySLfwipY#?secret=s5XQ6iReWb" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/rob-nicholson-gives-heads-up-on-new-social-enterprise-policy/">Rob Nicholson gives heads up on new social enterprise policy</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Rob Nicholson gives heads up on new social enterprise policy” — Changing Ireland" src="https://changingireland.ie/rob-nicholson-gives-heads-up-on-new-social-enterprise-policy/embed/#?secret=y3pOYt44qG#?secret=tlMjuSQztI" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Research finds that Dublin-based men’s health social enterprise represents “incredible value for money”.', 'https://changingireland.ie/wp-content/uploads/2024/03/This-works-Winner-for-measuring-social-impact-proves-how.png', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[{"slug":"community-development","title":"community development"},{"slug":"football","title":"football"},{"slug":"ildn","title":"ILDN"},{"slug":"irish-local-development-network-ildn","title":"Irish Local Development Network"},{"slug":"mens-health","title":"men''s health"},{"slug":"social-enterprise","title":"social enterprise"},{"slug":"social-enterprise-impact-awards","title":"Social Enterprise IMPACT Awards"},{"slug":"south-east-technological-university-setu","title":"South East Technological University SETU"},{"slug":"the-football-cooperative","title":"The Football Cooperative"}]', '', 253880, 1, '2024-03-19T11:39:24Z', '2024-05-31T14:49:32Z', '2024-03-19T11:39:24Z')
