INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Communities urged to sign up for Street Feast 2024', 'communities-urged-to-sign-up-for-street-feast-2024', '<p>The organisers of Street Feast, Ireland’s annual neighbourhood get-together, are calling on communities to register for this year’s event.</p>
<p>Now in its 14th year, Street Feast will be held over two days instead of one for the first time, taking place on May 25 and 26.</p>
<p>Speaking about the changes, Neighbourhood Network CEO and founder of Street Feast, Sam Bishop, said: “Running Street Feast over two days instead of one will give people more opportunity to celebrate together and plan around Ireland’s ever-changing weather. But the essence of Street Feast remains rooted in our mission to encourage neighbourly connections and camaraderie through shared meals, gatherings, games and conversations.”</p>
<p>Everyone is invited to participate and host gatherings, whether you live in an apartment of house. All you need is a space where people can come together to share a meal. Street Feast has had parties organised in front gardens, on streets and greens, in car parks, laneways, local parks and community centres.</p>
<p>Street Feast 2024 will see more than 1,250 communities take part.</p>
<p>To get involved, register now at <a href="https://streetfeast.ie/">StreetFeast.ie</a> to receive a free Street Feast party pack, including bunting, posters, invites and a DIY guide.</p>
<p>&nbsp;</p>', 'Street Feast will be held over two days for the first time this year on May 25 and 26. 1,250 neighbourhoods are to take part in the annual al fresco event', 'https://changingireland.ie/wp-content/uploads/2023/05/streetfeast2.jpg', '', '[{"slug":"events","title":"Events"}]', '[{"slug":"community","title":"Community"},{"slug":"community-development","title":"community development"},{"slug":"neighbourhood","title":"neighbourhood"},{"slug":"neighbourhood-network","title":"neighbourhood network"},{"slug":"rural-development","title":"rural development"},{"slug":"social-inclusion","title":"social inclusion"},{"slug":"street-feast","title":"Street Feast"}]', '', 253836, 1, '2024-03-08T11:35:42Z', '2024-03-07T11:52:42Z', '2024-03-08T11:35:42Z')
