INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New dog control group to tackle issue of restricted breeds', 'new-dog-control-group-to-tackle-issue-of-restricted-breeds', '<p>The group is made up of representatives from key Government Departments and interest groups and will make recommendations on strengthening the policy and legislation around dog control.</p>
<p>Minister for Rural and Community Development, Heather Humphreys says she has asked the group to examine the issue of restricting certain breeds of dogs, in line with actions being taken by regions in the UK, including Northern Ireland.</p>
<p>She also announced the appointment of former Deputy Garda Commissioner, John Twomey, as the independent chairperson of the group this week.</p>
<p>&#8220;As a dog owner myself, and someone from a farming background, I&#8217;m very conscious of the public concern about dog control. We have seen horrendous attacks by dogs on people, including children, in recent months and the issue of sheep worrying in our countryside continues to be a huge problem for our farmers,” said Minister Humphreys.</p>
<p>She added: &#8220;As Minister for Rural and Community Development, I have taken a series of measures already. These include the trebling of on-the-spot fines for the most serious dog control offences, as well as the provision of €2 million for dog warden services.</p>
<p>&#8220;But I do believe we need to take further action and that&#8217;s what this Stakeholder Group is going to consider.&#8221;</p>
<p>The group includes representatives from a broad range of interest groups, including farming and animal welfare organisations, such as the IFA, Comhairle na Tuaithe, the Irish Kennel Club and the ISPCA.</p>
<p>The Group will consider dog control issues under the policy remit of the Department of Rural and Community Development.</p>
<p>Discussions will focus on immediate improvements within the limitations of the current situation, whilst also scoping a way forward for longer term changes and improvements.</p>
<p>Themes include &#8216;restricted dogs&#8217; legislation, guidance on proper dog control, dog breeding establishment standards, and general awareness-raising.</p>', 'Restrictions on certain breeds of dogs will be one of the issues discussed by the newly-established Dog Control Stakeholder Group, which will hold its first meeting this month.', 'https://changingireland.ie/wp-content/uploads/2024/03/pexels-kush-laigude-7087788-scaled-e1709726471886.jpg', '', '[{"slug":"planning-governance","title":"Planning & Governance"}]', '[{"slug":"animal-welfare","title":"animal welfare"},{"slug":"comhairle-na-tuaithe","title":"Comhairle na Tuaithe"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"dog-control","title":"Dog control"},{"slug":"dog-control-stakeholder-group","title":"Dog Control Stakeholder Group"},{"slug":"dogs-trust","title":"Dogs Trust"},{"slug":"irish-farmers-association-ifa","title":"Irish Farmers Association IFA"},{"slug":"irish-kennel-club","title":"Irish Kennel Club"},{"slug":"ispca-irish-society-for-the-prevention-of-cruelty-to-animals","title":"ISPCA Irish Society for the Prevention of Cruelty to Animals"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"restricted-breeds","title":"restricted breeds"}]', '', 253824, 1, '2024-03-07T10:51:49Z', '2024-03-07T10:51:49Z', '2024-03-07T10:51:49Z')
