INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Rob Nicholson gives heads up on new social enterprise policy', 'rob-nicholson-gives-heads-up-on-new-social-enterprise-policy', '<p>The public consultation on social enterprise policy was held late last year and the draft new national social enterprise policy will be published shortly. Watch Rob speak here or read on for a summary:</p>
<div><iframe title="Rob Nicholson gives heads up on new social enterprise policy" width="696" height="392" src="https://www.youtube.com/embed/Qn6G8L28DFY?feature=oembed&#038;enablejsapi=1" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>
<p>“It’s still a nascent sector,” said Rob, noting that change will come quickly in the years ahead as EU law comes into force: “We’ve been flagging that inside government and across all the aspects of government.”</p>
<p>There will be five themes under the new policy which will run until 2027.</p>
<p>They will include an awareness-raising strand, a strand on access to finance, support for social enterprises with capacity go grow, and sustaining support for those who cannot scale up.</p>
<p>“Also for first time we’ll have a dedicated section on the green transition, taking a lead from the UN Sustainable Development Goals,” he said.<br />
“We are looking at national and international engagement. How do we make sure policy is implemented? And it’s a rapidly changing environment. We anticipate much more engagement with the EU in the future regarding social enterprise,” he added.</p>
<p>Rob said the Department&#8217;s policies have to be informed by evidence – which was one of the reasons he was present in Tullamore for the awards. Congratulating all who took part, he said measuring quantitative versus qualitative data is always a challenge. He thanked the ILDN for running the competition and adjudicating on the entries &#8211; <a href="https://changingireland.ie/trustworthy-social-enterprises-essential-to-combat-greenwashing-and-pinkwashing/">read our awards report here</a>.</p>
<blockquote><p><a href="https://changingireland.ie/trustworthy-social-enterprises-essential-to-combat-greenwashing-and-pinkwashing/">Trustworthy social enterprises essential to combat greenwashing and pinkwashing</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Trustworthy social enterprises essential to combat greenwashing and pinkwashing” — Changing Ireland" src="https://changingireland.ie/trustworthy-social-enterprises-essential-to-combat-greenwashing-and-pinkwashing/embed/#?secret=m1ZXPOBZZ8#?secret=HHS5iTFPiY" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/the-football-co-op-gives-a-e17-60-social-return-on-every-e1-invested/">The Football Co-op gives a €17.60 social return on every €1 invested</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“The Football Co-op gives a €17.60 social return on every €1 invested” — Changing Ireland" src="https://changingireland.ie/the-football-co-op-gives-a-e17-60-social-return-on-every-e1-invested/embed/#?secret=uIzDzXra7C#?secret=aAffYZPgMg" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/measuring-social-impact-learn-from-those-who-won-e45k/">Measuring social impact: Learn from those who won €45k</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Measuring social impact: Learn from those who won €45k” — Changing Ireland" src="https://changingireland.ie/measuring-social-impact-learn-from-those-who-won-e45k/embed/#?secret=lR4KEH6KhD#?secret=ylp3K8BLje" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Rob Nicholson works as a principal officer in the Department of Rural and Community Development (DRCD) with responsibility for the development and implementation of Ireland’s National Social Enterprise Policy and – speaking at a recent awards ceremony – he gave “a heads-up” on what to expect in the second iteration of that policy.', '', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"ildn","title":"ILDN"},{"slug":"irish-local-development-network-ildn","title":"Irish Local Development Network"},{"slug":"social-enterprise","title":"social enterprise"}]', '', 253897, 1, '2024-03-07T10:40:58Z', '2024-03-20T11:47:38Z', '2024-03-07T10:40:58Z')
