INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('‘We Are Human Too’ book launch celebrates disability activists', 'we-are-human-too-book-launch-celebrates-disability-activists', '<p>‘We Are Human Too’ is a moving anthology of interviews with disabled activists edited by Ann Marie Flanagan and co-produced by the Clare Leader Forum (CLF) that documents their crusade for equality.</p>
<p>According to CLF: “We have written the first and only socio-political book by disabled activists and researchers for everyone on how the State views our independence in the 100 years of Ireland&#8217;s. We track 30 years of disabled people&#8217;s emancipatory activism.</p>
<p>“We decided to write this book to ensure history is written through the lens of disabled people’s activism. This book includes 100 voices of disabled activists and allies from Clare and across the country, past and present.”</p>
<figure aria-describedby="caption-attachment-253827"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/03/Anne-Marie-Flanagan-and-Jacqui-Browne.jpg" alt="" width="1536" height="2048" srcset="https://changingireland.ie/wp-content/uploads/2024/03/Anne-Marie-Flanagan-and-Jacqui-Browne.jpg 1536w, https://changingireland.ie/wp-content/uploads/2024/03/Anne-Marie-Flanagan-and-Jacqui-Browne-225x300.jpg 225w, https://changingireland.ie/wp-content/uploads/2024/03/Anne-Marie-Flanagan-and-Jacqui-Browne-768x1024.jpg 768w, https://changingireland.ie/wp-content/uploads/2024/03/Anne-Marie-Flanagan-and-Jacqui-Browne-1152x1536.jpg 1152w, https://changingireland.ie/wp-content/uploads/2024/03/Anne-Marie-Flanagan-and-Jacqui-Browne-1080x1440.jpg 1080w" sizes="(max-width: 1536px) 100vw, 1536px" /><figcaption><em>&#8211; Anne Marie Flanagan and Jacqui Browne at the launch of &#8216;We Are Human Too&#8217; in Ennis on March 1</em></figcaption></figure>
<p>Speaking at the book launch in Ennis this month, Jacqui Browne complimented the work of Ann Marie Flanagan, alongside the role played by the late Donal Toolan and the Forum of People with Disabilities.</p>
<p>She also spoke of “the need for a paradigm shift based on principles of dignity, autonomy, equality, and inclusion”, and said that disability rights are “fundamental to the fabric of an inclusive society”.</p>
<p>Anyone interested in obtaining a copy of the book can message @LeaderClare on X or Facebook at <a href="mailto:Clare%20Leader%20Forum">Clare Leader Forum</a>, or email the CLF at clareleaderforum@gmail.com.</p>
<p>&nbsp;</p>', 'The Clare Leader Forum has launched a new book that puts the spotlight on the work of disabled activists.', 'https://changingireland.ie/wp-content/uploads/2024/03/book2.jpeg', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"}]', '[{"slug":"clare","title":"Clare"},{"slug":"clare-leader-forum","title":"Clare Leader Forum"},{"slug":"disability","title":"Disability"},{"slug":"disability-activists","title":"disability activists"},{"slug":"ennis-book-club-festival","title":"Ennis Book Club Festival"},{"slug":"equality","title":"Equality"},{"slug":"people-with-disabilities","title":"people with disabilities"}]', '', 253826, 1, '2024-03-06T12:30:15Z', '2024-03-06T12:30:15Z', '2024-03-06T12:30:15Z')
