INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Biggest expansion of National Walks Scheme adds 62 new trails', 'biggest-expansion-of-national-walks-scheme-adds-62-new-trails', '<p>Counties Monaghan and Wexford will welcome their first National Walks Scheme trails, with the development of the Monaghan Way, and five walks in Wexford, such as the Mount Nebo trail.</p>
<p>The expansion also includes five trails on two offshore islands – Inis Meáin and Oileán Chléire.</p>
<p>&#8220;I want to make Ireland an international destination of choice for walkers and hikers. We have a unique offering in terms of our natural landscape filled with mountains, forests, lakes, rivers and sea,” commented Minister for Rural and Community Development, Heather Humphreys.</p>
<p>Among the new Walks Scheme trails announced this week are:</p>
<ul>
<li>Carrigmeal Woodland Loops, Co Laois</li>
<li>Strickeen Mountain Walk, Co Kerry</li>
<li>The Devils Chimney, Co Sligo</li>
<li>Ardmore Cliff Walk, Co Waterford</li>
<li>Six Fastnet Trails, Co Cork</li>
</ul>
<figure aria-describedby="caption-attachment-253818"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/02/IMG_3828-scaled.jpg" alt="" width="2560" height="1707" srcset="https://changingireland.ie/wp-content/uploads/2024/02/IMG_3828-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2024/02/IMG_3828-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2024/02/IMG_3828-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2024/02/IMG_3828-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2024/02/IMG_3828-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2024/02/IMG_3828-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2024/02/IMG_3828-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption><em>&#8211; One of the new trails being added to the Walks Scheme is Bóthar Na Naomh Walking Trail in Cloone, Co Leitrim. Pictured with Minister Humphreys at the trail are local walkers Lily Mitchell (left) and Collette Charles (right). Photo: Brian Duignan</em></figcaption></figure>
<p>The total number of nationally recognised trails now stands at over 140, up from just 40 trails in 2019.</p>
<p>The initiative is designed to boost outdoor recreation and rural tourism, and is a key element of Embracing Ireland&#8217;s Outdoors, the National Outdoor Recreation Strategy.</p>
<p>Under the Walks Scheme, funding is provided to farmers and other landholders to maintain the walking trails that go through their holdings.</p>
<p>Over €15 million has been paid to farmers and landholders participating on the Scheme since 2017, with an additional €1.4 million spent on materials for the maintenance of trails.</p>
<p>This expansion will see an additional annual investment of over €500,000 to rural areas through the scheme.</p>
<p>Minister Humphreys said: &#8220;Often these amenities can only be truly appreciated by crossing through fields and land owned by local farmers. The National Walks Scheme is about working in partnership with landowners so we can open up access to local communities and tourists to enjoy these wonderful hidden gems we have all across Ireland.</p>
<p>&#8220;I want to acknowledge and thank the work of all the farmers and landowners involved in the Walks Scheme who provide access to their holdings and who help to maintain the trails to a high standard for the benefit of a huge number of locals and visitors.</p>
<p>&#8220;Without the goodwill of farmers, we would not have access to many of our favourite tracks and trails. It is incumbent on all of us to use these amenities responsibly, respect local landowners and of course – Leave No Trace.&#8221;</p>
<p>The Scheme is operated by the Department of Rural and Community Development in conjunction with Local Development Companies. The Department is now inviting expressions of interest from LDCs for new trails and substantial extensions to existing trails.</p>
<p>Potential applicants, such as trail management committees, community groups, local authorities, and other similar entities, are advised that expressions of interest must be made through LDCs.</p>
<p>The closing date is October 11.</p>
<p>The full list of trails approved in this expansion can be found <a href="https://www.gov.ie/en/press-release/e0468-our-rural-future-minister-humphreys-adds-62-new-trails-to-the-national-walks-scheme/">here</a>.</p>
<p>&nbsp;</p>', 'The largest ever expansion of Ireland’s National Walks Scheme was announced this week, promising to add 62 new walking and hiking trails across 17 counties.', 'https://changingireland.ie/wp-content/uploads/2024/02/20230407_130012-scaled.jpg', '', '[{"slug":"initiatives","title":"Initiatives"}]', '[{"slug":"community-development","title":"community development"},{"slug":"cork","title":"Cork"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"embracing-irelands-outdoors","title":"Embracing Ireland''s Outdoors"},{"slug":"ireland","title":"Ireland"},{"slug":"kerry","title":"Kerry"},{"slug":"laois","title":"Laois"},{"slug":"local-development-companies","title":"local development companies"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"monaghan","title":"Monaghan"},{"slug":"national-outdoor-recreation-strategy","title":"national outdoor recreation strategy"},{"slug":"national-walks-scheme","title":"National Walks Scheme"},{"slug":"outdoor-recreation","title":"outdoor recreation"},{"slug":"rural-development","title":"rural development"},{"slug":"sligo","title":"Sligo"},{"slug":"tourism","title":"tourism"},{"slug":"waterford","title":"Waterford"},{"slug":"wexford","title":"Wexford"}]', '', 253817, 1, '2024-02-29T11:59:31Z', '2024-02-29T12:00:40Z', '2024-02-29T11:59:31Z')
