INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('The search is on for Ireland’s humanitarian heroes', 'the-search-is-on-for-irelands-humanitarian-heroes', '<p>The event aims to shine a national spotlight on the selfless efforts of individuals, organisations and businesses in Ireland who have helped those in need and contributed to the betterment of society.</p>
<p>According to the Irish Red Cross: “A humanitarian is someone who has used their talent, time and passion to assist others. A humanitarian can be anyone, whether they are a world leader, local volunteer, business professional or community worker.</p>
<p>“They can be old or young, a journalist, a store owner, a musician, anyone at all.”</p>
<p>The nomination categories include: Humanitarian of the Year, Young Humanitarian of the Year, Humanitarian Group/Organisation of the Year, Humanitarian Journalist of the Year, Corporate Impact and Lifetime Achievement.</p>
<p>“Since 2018 the Irish Red Cross has celebrated this group of inspiring and remarkable people through our annual presentation of the Humanitarian Awards.</p>
<p>“In hosting this event we intend to publicly recognise the inspiring examples of compassion demonstrated by our nominees and award winners,” added the organisation.</p>
<p>Nominations can be made on the awards website: <strong><a href="http://irchumanitarianawards.ie/submit-a-nomination">irchumanitarianawards.ie/submit-a-nomination</a></strong>.</p>
<p>The deadline for submissions is March 23, and the 2024 Irish Red Cross Humanitarian Awards presentation will take place on May 14 at the Royal College of Physicians on Kildare Street in Dublin.</p>
<p>&nbsp;</p>
<p><strong> </strong></p>
<p>&nbsp;</p>', 'The Irish Red Cross this week announced that they are calling on members of the public to submit nominations for their 2024 Humanitarian Awards.', 'https://changingireland.ie/wp-content/uploads/2024/02/RUBY-OKELLY-young-humanitarian-of-the-year-2023.jpg', '', '[{"slug":"events","title":"Events"}]', '[{"slug":"2024-irish-red-cross-humanitarian-awards","title":"2024 Irish Red Cross Humanitarian Awards"},{"slug":"awards","title":"awards"},{"slug":"dublin","title":"Dublin"},{"slug":"humanitarian","title":"Humanitarian"},{"slug":"irish-red-cross","title":"Irish Red Cross"},{"slug":"royal-college-of-physicians","title":"Royal College of Physicians"}]', '', 253801, 1, '2024-02-22T14:07:50Z', '2024-02-22T14:07:54Z', '2024-02-22T14:07:50Z')
