INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Members of public invited to join Advisory Group on Racism and Racial Equality', 'members-of-public-invited-to-join-advisory-group-on-racism-and-racial-equality', '<p>The group will be tasked with monitoring and helping to progress the implementation of the National Action Plan Against Racism (NAPAR) 2023-2027.</p>
<p>The NAPAR was developed by an independent Anti-Racism Committee, and accepted by the Government in 2023.</p>
<p>The Department of Children, Equality, Disability, Integration and Youth is now seeking expressions of interest from members of the public who feel they can contribute to the successful implementation of the NAPAR through membership of this Advisory Group.</p>
<p>According to the Department: “The NAPAR proposes actions to help make Ireland a place in which the impacts of racism are fully acknowledged and actively addressed. It was developed by an independent Anti-Racism Committee and published in March 2023. The Advisory Group will assist in the ongoing implementation of the plan. The Ireland Against Racism Fund, a key action under the plan, committed €1.2 million to anti-racism projects across Ireland through 2023 and 2024.”</p>
<p>Minister O’Brien commented: “The establishment of an independent Advisory Group underlines the government’s commitment to tackling racism throughout society. This group will be integral to the support systems established under the NAPAR and will be critical to the successful implementation of the plan.”</p>
<p>Applications can be made online <a href="https://ec.europa.eu/eusurvey/runner/NAPARAdvisoryCouncilEOI">here.</a> The closing date is Friday March 8 at 1pm.</p>', 'Minister of State for Community Development, Integration, and Charities Joe O’Brien has this week announced the publication of an expression of interest campaign for the Advisory Group on Racism and Racial Equality.', 'https://changingireland.ie/wp-content/uploads/2024/02/NAPAR-Cover-image-e1707309085179.png', '', '[{"slug":"policy-strategy","title":"Policy & Strategy"}]', '[{"slug":"advisory-group-on-racism-and-racial-equality","title":"Advisory Group on Racism and Racial Equality"},{"slug":"anti-racism-committee","title":"Anti-Racism Committee"},{"slug":"department-of-children-equality-disability-integration-and-youth","title":"Department of Children Equality Disability Integration and Youth"},{"slug":"ireland-against-racism-fund","title":"Ireland Against Racism Fund"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"national-action-plan-against-racism","title":"National Action Plan Against Racism"}]', '', 253788, 1, '2024-02-09T10:56:48Z', '2024-02-09T10:56:48Z', '2024-02-09T10:56:48Z')
