INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('‘Town Teams’ of local residents to help develop Ireland’s rural towns and villages', 'town-teams-of-local-residents-to-help-develop-irelands-rural-towns-and-villages', '<p>The funding for rural towns and villages announced by Minister for Rural and Community Development Heather Humphreys today also includes €50,000 each for the development of a number of projects designed to breathe new life into rural communities.</p>
<p>Additional funding will be provided for such projects in counties in the North West.</p>
<p>Towns will also be provided with up to €30,000 in funding to develop their own Town Centre First (TCF) Plans.</p>
<p>In addition, financial supports will be provided for smaller towns to tackle vacancy and dereliction.</p>
<p>Minister Humphreys commented: &#8220;This is about empowering our communities to realise their vision. It&#8217;s about giving them the tools and supports they need to generate investment, attract tourism and above all, become better places to live, work and raise a family.</p>
<p>&#8220;Central to this multi-million Euro initiative is the establishment of a new Town Team Support Fund. We all know that our Town Teams do fantastic work in many parts of the country. But in other parts, there is no Town Team at all.</p>
<p>&#8220;So under this new fund, we are going to provide up to €10,000 per town to help them establish a new Town Team or to build up the one already in place.</p>
<p>&#8220;This significant package of supports will be administered through the local authorities and the Town Regeneration Officers and I&#8217;m encouraging all communities to get involved.&#8221;</p>
<p>A Town Team is a group of local residents, businesspeople, community representatives and other stakeholders. They are supported in their work by Town Regeneration Officers.</p>
<p>Details of the Town Centre First initiative can be found <a href="https://www.gov.ie/en/publication/473d3-town-centre-first-policy/">here</a></p>
<p>A full list of towns who have previously completed Town Centre First plans can be found <a href="https://www.gov.ie/en/publication/473d3-town-centre-first-policy/#town-centre-first-initiative-phase-1">here</a></p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>', 'A new €4.5 million funding package will include funding to develop a network of Town Teams that will “make their area a better place to live, work, visit and invest in”.', 'https://changingireland.ie/wp-content/uploads/2024/02/bailieborough.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"community-development","title":"community development"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"minister-heather-hunphreys","title":"Minister Heather Hunphreys"},{"slug":"our-rural-future","title":"Our Rural Future"},{"slug":"regeneration","title":"regeneration"},{"slug":"rural-development","title":"rural development"},{"slug":"rural-towns","title":"rural towns"},{"slug":"town-centre-first","title":"Town Centre First"},{"slug":"town-regeneration-officers","title":"Town Regeneration Officers"},{"slug":"town-team","title":"Town Team"}]', '', 253785, 1, '2024-02-07T12:05:32Z', '2024-02-07T12:05:32Z', '2024-02-07T12:05:32Z')
