INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('ILMI launches strategic plan for “a more inclusive Ireland”', 'ilmi-launches-strategic-plan-for-a-more-inclusive-ireland', '<p>The plan outlines ILMI’s strategy to build local structures and actively contribute to policy development and implementation at both local and national levels.</p>
<p>Emphasising investment in disabled people, the plan supports activists in working collectively “to ensure the authentic collective voice of disabled people shapes a more inclusive Ireland”.</p>
<p>Launching the plan was Minister of State with Special Responsibility for Disabilities, Anne Rabbitte.</p>
<p>“ILMI’s dedication to creating an inclusive Ireland aligns with our national goals for the empowerment and wellbeing of disabled people. This strategic plan is a testament to the organisation’s vital role in shaping policies that foster freedom, choice, and control. I commend ILMI for their impactful work and look forward to witnessing the positive transformations this plan will bring to the lives of disabled people across Ireland,” commented the Minister.</p>
<p>Des Kenny, ILMI’s chairperson, said: “This strategic plan has its origins in the noble tradition of disabled people being actively engaged in our own activism for four decades now. The power of collective advocacy within a Disabled Persons Organisation (DPO) is unparalleled. It transforms the conversation from ‘I think’ to ‘we think,’ providing evidence of how inclusion must be resourced: mapping the inclusion landscape to real, meaningful change.”</p>
<p>CEO of ILMI, Damien Walshe expressed his gratitude to &#8220;the incredible individuals who meticulously crafted our strategic plan&#8221;.</p>
<p>He continued: &#8220;As a national cross-impairment DPO, ILMI&#8217;s vision revolves around creating a society where disabled people enjoy freedom, choice, and control over all aspects of our lives. Our strategic plan is not just a document; it&#8217;s a roadmap for transformative change within our organisation and beyond.</p>
<p>&#8220;We express our gratitude to Values Lab for their expertise in crafting a robust, values-led plan that reflects the aspirations of our community.&#8221;</p>
<p>PDF link to the Strategic Plan is here: <a href="https://ilmi.ie/wp-content/uploads/2023/11/ILMI-Strategic-Plan-2024-to-2027.pdf?fbclid=IwAR2aceg2Ce0G8GakSlEhF5BjgWrAs7UXjrUZTN3V76XHG_oO2nIfGRD0GnE">https://ilmi.ie/&#8230;/11/ILMI-Strategic-Plan-2024-to-2027.pdf</a></p>
<p>&nbsp;</p>', 'Independent Living Movement Ireland (ILMI) has launched a new strategic plan, which it describes as “solidifying its commitment to championing the rights and inclusion of disabled people nationwide”.', 'https://changingireland.ie/wp-content/uploads/2023/12/406321319_739237488248048_5618192174756227543_n.jpg', '', '[{"slug":"empowerment","title":"Empowerment"}]', '[{"slug":"disability","title":"Disability"},{"slug":"disability-activism","title":"Disability Activism"},{"slug":"disability-equality","title":"disability equality"},{"slug":"equality","title":"Equality"},{"slug":"inclusion","title":"Inclusion"},{"slug":"independent-living-movement-ireland-ilmi","title":"Independent Living Movement Ireland (ILMI)"},{"slug":"minister-for-disability-anne-rabbitte","title":"Minister for Disability Anne Rabbitte"},{"slug":"policy","title":"policy"},{"slug":"strategic-plan","title":"Strategic plan"}]', '', 253670, 1, '2023-12-08T10:16:59Z', '2023-12-06T12:41:10Z', '2023-12-08T10:16:59Z')
